        //                 "instType": "SPOT",
        //                 "instId": "BTC-USDT",
        //                 "last": "31500.1",
        //                 "lastSz": "0.00001754",
        //                 "askPx": "31500.1",
        //                 "askSz": "0.00998144",
        //                 "bidPx": "31500",
        //                 "bidSz": "3.05652439",
        //                 "open24h": "31697",
        //                 "high24h": "32248",
        //                 "low24h": "31165.6",
        //                 "sodUtc0": "31385.5",
        //                 "sodUtc8": "32134.9",
        //                 "volCcy24h": "503403597.38138519",
        //                 "vol24h": "15937.10781721",
        //                 "ts": "1626526618762"
        //             }
        //         ]
        //     }
        //
        // bbo-tbt
        //
        //     {
        //         "arg": { "channel": "bbo-tbt", "instId": "BTC-USDT" },
        //         "data": [
        //             {
        //                 "asks": [ [ "36232.2", "1.8826134", "0", "17" ] ],
        //                 "bids": [ [ "36232.1", "0.00572212", "0", "2" ] ],
        //                 "ts": "1651826598363"
        //             }
        //         ]
        //     }
        //
        let arg: crate::value::Dict = message.key_dict("arg");
        let marketId: Option<String> = self.safe_string_k_opt(&arg, "instId", &[]);
        let market: crate::types::Market = self.safe_market(marketId.as_deref(), None, &[]);
        let data: Vec<crate::value::Dict> = crate::value::dict_rows(message.key_list("data"));
